(function(){
  let uid = 1;
  const newId = () => 'i' + (uid++);

  let categories = [
    { id: newId(), name: 'Sospechosos', items: [
        { id: newId(), name: 'Coronel' },
        { id: newId(), name: 'Profesora' },
        { id: newId(), name: 'Bibliotecario' }
    ]},
    { id: newId(), name: 'Lugares', items: [
        { id: newId(), name: 'Biblioteca' },
        { id: newId(), name: 'Capilla' },
        { id: newId(), name: 'Aula' }
    ]},
    { id: newId(), name: 'Armas', items: [
        { id: newId(), name: 'Lápiz' },
        { id: newId(), name: 'Cantimplora' },
        { id: newId(), name: 'Cuerda' }
    ]}
  ];

  let cellStates = {};

  function cellKey(a, b){
    return a < b ? a + '|' + b : b + '|' + a;
  }

  const editorEl = document.getElementById('categoriesEditor');

  function renderEditor(){
    editorEl.innerHTML = '';
    categories.forEach(cat => {
      const card = document.createElement('div');
      card.className = 'cat-card';

      const head = document.createElement('div');
      head.className = 'cat-card-head';

      const nameInput = document.createElement('input');
      nameInput.type = 'text';
      nameInput.value = cat.name;
      nameInput.addEventListener('input', e => {
        cat.name = e.target.value;
        renderBoard();
      });
      head.appendChild(nameInput);

      if (categories.length > 2){
        const rm = document.createElement('button');
        rm.className = 'remove-cat';
        rm.textContent = '✕';
        rm.title = 'Eliminar categoría';
        rm.addEventListener('click', () => {
          categories = categories.filter(c => c.id !== cat.id);
          renderEditor();
          renderBoard();
        });
        head.appendChild(rm);
      }
      card.appendChild(head);

      cat.items.forEach(item => {
        const row = document.createElement('div');
        row.className = 'item-row';

        const itemInput = document.createElement('input');
        itemInput.type = 'text';
        itemInput.value = item.name;
        itemInput.addEventListener('input', e => {
          item.name = e.target.value;
          renderBoard();
        });
        row.appendChild(itemInput);

        const rmItem = document.createElement('button');
        rmItem.className = 'icon-btn';
        rmItem.textContent = '−';
        rmItem.title = 'Eliminar elemento';
        rmItem.addEventListener('click', () => {
          cat.items = cat.items.filter(it => it.id !== item.id);
          renderEditor();
          renderBoard();
        });
        row.appendChild(rmItem);

        card.appendChild(row);
      });

      const addItemBtn = document.createElement('button');
      addItemBtn.className = 'add-item-btn';
      addItemBtn.textContent = '+ elemento';
      addItemBtn.addEventListener('click', () => {
        cat.items.push({ id: newId(), name: 'Nuevo' });
        renderEditor();
        renderBoard();
      });
      card.appendChild(addItemBtn);

      editorEl.appendChild(card);
    });
  }

  document.getElementById('addCatBtn').addEventListener('click', () => {
    categories.push({
      id: newId(),
      name: 'Categoría ' + (categories.length + 1),
      items: [{ id: newId(), name: 'Elemento 1' }, { id: newId(), name: 'Elemento 2' }]
    });
    renderEditor();
    renderBoard();
  });

  const boardWrap = document.getElementById('boardWrap');

  function nextState(s){ return (s + 1) % 3; }

  function renderBoard(){
    boardWrap.innerHTML = '';
    const n = categories.length;
    if (n < 2){
      boardWrap.innerHTML = '<p class="empty-hint">Añade al menos dos categorías para generar el tablero.</p>';
      return;
    }

    const colCats = categories.slice(0, n - 1);
    const rowCats = categories.slice(1).reverse();

    const table = document.createElement('table');
    table.id = 'board';

    const headRow = document.createElement('tr');
    const corner = document.createElement('th');
    corner.className = 'corner';
    headRow.appendChild(corner);
    colCats.forEach((cat, ci) => {
      cat.items.forEach((item, ii) => {
        const th = document.createElement('th');
        th.textContent = item.name || '—';
        if (ii === 0 && ci > 0) th.classList.add('group-gap');
        headRow.appendChild(th);
      });
    });
    table.appendChild(headRow);

    rowCats.forEach((rowCat, riIdx) => {
      const realRowIndex = n - 1 - riIdx;
      rowCat.items.forEach((rowItem, itemIdx) => {
        const tr = document.createElement('tr');
        if (itemIdx === 0 && riIdx > 0) tr.classList.add('group-gap-row');

        const th = document.createElement('th');
        th.textContent = rowItem.name || '—';
        tr.appendChild(th);

        colCats.forEach((colCat, ciIdx) => {
          const valid = realRowIndex > ciIdx;
          colCat.items.forEach((colItem, colItemIdx) => {
            const td = document.createElement('td');
            if (colItemIdx === 0 && ciIdx > 0) td.classList.add('group-gap');

            if (!valid){
              td.classList.add('blocked');
            } else {
              const key = cellKey(rowItem.id, colItem.id);
              const state = cellStates[key] || 0;
              const btn = document.createElement('button');
              btn.className = 'cell-btn';
              if (state === 1){ btn.textContent = 'X'; btn.classList.add('state-x'); }
              else if (state === 2){ btn.textContent = '✓'; btn.classList.add('state-o'); }
              btn.title = rowItem.name + ' × ' + colItem.name;
              btn.addEventListener('click', () => {
                cellStates[key] = nextState(state);
                renderBoard();
              });
              td.appendChild(btn);
            }
            tr.appendChild(td);
          });
        });

        table.appendChild(tr);
      });
    });

    boardWrap.appendChild(table);
  }

  document.getElementById('clearBoard').addEventListener('click', () => {
    cellStates = {};
    renderBoard();
  });

  renderEditor();
  renderBoard();
})();

