  render() {
    const container = document.getElementById('solverContent');
    if (!container) return;

    let html = '<div class="solver-book-select">';
    this.books.forEach(book => {
      html += `<button class="solver-book-btn" data-book-id="${book.id}">${book.name}</button>`;
    });
    html += '</div><div id="solverCases"></div>';

    container.innerHTML = html;

    const buttons = container.querySelectorAll('.solver-book-btn');
    buttons.forEach(btn => {
      btn.addEventListener('click', () => {
        buttons.forEach(b => b.classList.remove('selected'));
        btn.classList.add('selected');
        this.selectBook(parseInt(btn.dataset.bookId));
      });
    });

    if (buttons.length > 0) {
      buttons[0].click();
    }
  },

  selectBook(bookId) {
    this.currentBook = this.books.find(b => b.id === bookId);
    const puzzles = this.puzzles[bookId];
    const container = document.getElementById('solverCases');

    if (!puzzles || Object.keys(puzzles).length === 0) {
      container.innerHTML = '<p class="solver-empty">No hay casos disponibles.</p>';
      return;
    }

    const puzzleNums = Object.keys(puzzles).sort((a, b) => parseInt(a) - parseInt(b));
    let html = '<div style="margin-bottom: 16px;"><select id="puzzleSelect" style="padding: 10px 14px; font-size: 14px; border-radius: 4px; border: 1px solid var(--paper-line); background: var(--paper); color: var(--ink); font-family: inherit; min-width: 200px;">';
    html += '<option value="">Selecciona un caso</option>';
    puzzleNums.forEach(num => {
      html += `<option value="${num}">Caso ${num}</option>`;
    });
    html += '</select></div><div id="puzzleDetails"></div>';

    container.innerHTML = html;

    document.getElementById('puzzleSelect').addEventListener('change', (e) => {
      this.showPuzzle(e.target.value);
    });
  },

  showPuzzle(puzzleNum) {
    const puzzles = this.puzzles[this.currentBook.id];
    const puzzle = puzzles[puzzleNum];
    const container = document.getElementById('puzzleDetails');

    if (!puzzle) {
      container.innerHTML = '';
      return;
    }

    let html = `<div class="solver-case"><h3>Caso ${puzzleNum}</h3>`;

    puzzle.questions.forEach((q, idx) => {
      const safeId = `q${puzzleNum}_${idx}`;
      html += `
        <div class="solver-question">
          <label for="${safeId}">${q.type}?</label>
          <select id="${safeId}">
            <option value="">Selecciona...</option>
            ${q.options.map(opt => `<option value="${opt}">${opt}</option>`).join('')}
          </select>
        </div>
      `;
    });

    html += `
      <div class="solver-actions">
        <button id="checkBtn">Verificar respuestas</button>
        <button id="resetBtn">Limpiar</button>
      </div>
      <div id="solverResult"></div>
    `;
    html += '</div>';

    container.innerHTML = html;

    document.getElementById('checkBtn').addEventListener('click', () => this.checkSolution(puzzleNum));
    document.getElementById('resetBtn').addEventListener('click', () => this.resetSolution(puzzleNum));
  },

  checkSolution(puzzleNum) {
    const puzzle = this.puzzles[this.currentBook.id][puzzleNum];
    const resultContainer = document.getElementById('solverResult');
    let correct = 0;
    let total = puzzle.questions.length;

    puzzle.questions.forEach((q, idx) => {
      const safeId = `q${puzzleNum}_${idx}`;
      const select = document.getElementById(safeId);
      select.classList.remove('correct', 'incorrect');

      if (select.value === q.correct) {
        correct++;
        select.classList.add('correct');
      } else if (select.value !== '') {
        select.classList.add('incorrect');
      }
    });

    if (correct === total) {
      resultContainer.innerHTML = `<div class="solver-result success">¡Felicidades! Has resuelto el Caso ${puzzleNum} correctamente.</div>`;
    } else {
      resultContainer.innerHTML = `<div class="solver-result error">Has acertado ${correct} de ${total}. ¡Sigue intentando!</div>`;
    }
  },

  resetSolution(puzzleNum) {
    const puzzle = this.puzzles[this.currentBook.id][puzzleNum];

    puzzle.questions.forEach((q, idx) => {
      const safeId = `q${puzzleNum}_${idx}`;
      const select = document.getElementById(safeId);
      if (select) {
        select.value = '';
        select.classList.remove('correct', 'incorrect');
      }
    });

    const resultContainer = document.getElementById('solverResult');
    if (resultContainer) resultContainer.innerHTML = '';
  },

